 const settings=$('settingsView'),design=[...settings.querySelectorAll(':scope>details')].find(x=>x.textContent.includes('Farbschema'));
 if(design)settings.querySelector('h2').after(design);const manage=document.createElement('button');manage.type='button';manage.className='secondary wide';manage.textContent='Konten verwalten';manage.onclick=()=>{showView('accounts');$('accountsView').scrollIntoView({block:'start'});};design?.after(manage);
 const advanced=document.createElement('details');advanced.className='card settings-group';const summary=document.createElement('summary');summary.textContent='Erweitert · Daten & Diagnose';advanced.append(summary);for(const d of [...settings.querySelectorAll(':scope>details')])if(d!==design&&!d.textContent.includes('Setups &'))advanced.append(d);settings.append(advanced);
 const setupManager=$('setupManager').closest('details');setupManager.querySelector('summary').textContent='Setup-Katalog verwalten';$('playbookView').append(setupManager);const create=document.createElement('button');create.type='button';create.className='ghost wide';create.textContent='＋ Setup anlegen / Katalog verwalten';create.onclick=()=>{setupManager.open=true;setupManager.scrollIntoView({block:'start'});};$('playbookView').querySelector('h2').after(create);
 $('playbookView').querySelectorAll(':scope>p,.card>p').forEach(p=>p.hidden=true);
 const accountTools=document.createElement('details');accountTools.className='card';const st=document.createElement('summary');st.textContent='Session-Konten & Vorgaben';accountTools.append(st,$('sessionAccountsSummary'),$('changeSessionAccounts'));$('sessionHub').querySelector('.session-hub-heading').after(accountTools);
 const flow=document.createElement('div');flow.className='flow-step';flow.textContent='VOR DEM TRADE · Setup → Idee → Risiko → Verfassung → Entry';$('entryForm').prepend(flow);
 const ideaOnly=document.createElement('label');ideaOnly.className='account-pick';ideaOnly.innerHTML='<input type="checkbox" id="ideaOnly"> Nur Idee vorbereiten · noch keinen Trade erfassen';$('ttIdeaMode').closest('label').before(ideaOnly);ideaOnly.querySelector('input').onchange=e=>{const v=e.target.checked;$('recordEntry').hidden=v;$('ttSaveIdea').closest('details').open=v;$('entryAccounts').classList.toggle('hidden',v);$('entryEmotionOptions').closest('.emotion-section').classList.toggle('hidden',v);};
 const search=document.createElement('input');search.type='search';search.placeholder='Setup im Playbook suchen';search.setAttribute('aria-label','Setup suchen');search.oninput=()=>{$('playbookLexicon').querySelectorAll('.book-entry').forEach(x=>x.hidden=!x.querySelector('summary').textContent.toLowerCase().includes(search.value.toLowerCase()));};$('playbookLexicon').before(search);
 for(const [id,label,options] of [['ttCorners','Ecken',[['round','Rund'],['square','Kantig']]],['ttText','Schrift',[['normal','Standard'],['large','Größer']]],['ttMotion','Bewegung',[['normal','Standard'],['reduce','Reduziert']]]]){const l=document.createElement('label');l.textContent=label;const select=document.createElement('select');select.id=id;for(const [v,t]of options){const o=document.createElement('option');o.value=v;o.textContent=t;select.append(o);}let value='';try{value=localStorage.getItem('tt8_'+id)||options[0][0];}catch(_){}select.value=value;document.body.dataset[id]=value;const apply=()=>{document.body.dataset[id==='ttCorners'?'ttCorners':id==='ttText'?'ttText':'ttMotion']=select.value;try{localStorage.setItem('tt8_'+id,select.value);}catch(_){};};apply();select.onchange=apply;l.append(select);design?.append(l);}
 const history=document.createElement('details');history.className='card';const hs=document.createElement('summary');hs.textContent='Sessions ansehen';history.append(hs);const content=document.createElement('div');content.id='sessionHistoryContent';history.append(content);history.addEventListener('toggle',async()=>{if(!history.open)return;content.textContent='Wird geladen …';try{await loadSessionIndex(true);content.replaceChildren();for(const sess of sessionIndex.values()){const b=document.createElement('button');b.type='button';b.className='ghost wide';b.textContent=sessionLabel(sess);b.onclick=async()=>{const owner=currentUser?.id;const rows=await readAllRows('trades','*',q=>q.eq('session_id',sess.id).order('entry_at',{ascending:true}).order('id'));if(owner!==currentUser?.id)return;journalScope='history';showView('journal');setJournalHeading(sessionLabel(sess));$('sessionFinishPanel').classList.add('hidden');$('sessionTrades').classList.remove('hidden');$('tradeDetails').classList.add('hidden');const list=$('sessionTradeList');list.classList.remove('hidden');list.replaceChildren();for(const t of rows){const btn=document.createElement('button');btn.type='button';btn.className='ghost wide';btn.textContent=tradeLabel(t)+' · '+t.setup_type+' · '+(t.exit_at?reviewStatusText(t):'Läuft');btn.onclick=()=>openJournalTradeById(t.id);list.append(btn);}if(!rows.length)list.textContent='Diese Session hat keine Trades.';list.scrollIntoView({block:'start'});};content.append(b);}}catch(e){content.textContent=e.message;}});$('morningDashboard').before(history);
