let trainingRevisionPending=null;
async function reviseTrainingFocus(rule,source){if(!source||trainingFocusBusy)return false;const owner=currentUser?.id;if(rule.trim().length<10||rule.trim().length>500)throw new Error('Bitte eine konkrete Regel mit 10–500 Zeichen eingeben.');if(!confirm('Regel für kommende Trades präzisieren? Bisherige Trades und ihre Trainingsregel bleiben unverändert.'))return false;if(!trainingRevisionPending||trainingRevisionPending.owner!==owner||trainingRevisionPending.expected!==source.id||trainingRevisionPending.goal!==rule.trim())trainingRevisionPending={owner,expected:source.id,goal:rule.trim(),id:crypto.randomUUID()};trainingFocusBusy=true;try{const {data,error}=await client.rpc('revise_training_focus_v741',{p_request_id:trainingRevisionPending.id,p_expected_id:trainingRevisionPending.expected,p_goal:trainingRevisionPending.goal});if(currentUser?.id!==owner)return false;if(error)throw error;if(!data?.id)throw new Error('Keine Speicherbestätigung');trainingRevisionPending=null;$('trainingGoal').value='';await loadTrainingFocus();trainingFocusMessage('Regel präzisiert · gilt für kommende Trades.');return true;}finally{trainingFocusBusy=false;drawTrainingFocus();}}
async function addIdeaEvidence(host,idea,attempts){const owner=currentUser?.id;await appendSessionEvidence(host,idea.session_id);if(owner!==currentUser?.id||!host.isConnected)return;const gallery=document.createElement('details');gallery.className='card';gallery.open=true;const title=document.createElement('summary');title.textContent='Charts zur Idee · '+attempts.length+' Versuche';gallery.append(title);host.querySelector('form')?.before(gallery);if(!gallery.isConnected)host.append(gallery);let count=0;for(const a of attempts){const prefix=chartPath('trade',a.trade_id,'');const {data,error}=await client.storage.from(CHART_BUCKET).list(prefix,{limit:100,sortBy:{column:'created_at',order:'asc'}});if(owner!==currentUser?.id||!gallery.isConnected)return;if(error){const p=document.createElement('p');p.textContent='Versuch '+a.attempt_number+': Bilder nicht geladen';gallery.append(p);continue;}for(const f of data||[]){if(!f.id||!f.name)continue;const path=prefix+f.name,url=await signedChart(path);if(owner!==currentUser?.id||!gallery.isConnected)return;const p=document.createElement('p');p.textContent='Versuch '+a.attempt_number;gallery.append(p);makeChartPreview(gallery,path,url);count++;}}if(!count){const p=document.createElement('p');p.className='compact-help';p.textContent='Noch keine LTF-Charts verknüpft. Über den jeweiligen Versuch ergänzen.';gallery.append(p);}}
initGuidedFlow();
const originalSetupCards=renderSetupCards;renderSetupCards=function(){originalSetupCards();renderSetupGuide();};
$('refreshPlaybookLexicon').addEventListener('click',()=>{void renderBook();});
