const editGoal=document.createElement('button');editGoal.type='button';editGoal.id='editTrainingGoal';editGoal.className='ghost wide';editGoal.textContent='Trainingsregel präzisieren';$('trainingGoal').closest('label').after(editGoal);editGoal.onclick=()=>{if(!trainingFocusActive){trainingFocusMessage('Zuerst einen Schwerpunkt aus den dokumentierten Mustern übernehmen.');return;}$('trainingGoal').readOnly=false;editGoal.hidden=true;const save=document.createElement('button');save.type='button';save.textContent='Präzisierte Regel für neue Trades speichern';editGoal.after(save);save.onclick=async()=>{const source=trainingFocusActive;try{if(await reviseTrainingFocus($('trainingGoal').value,source)){save.remove();editGoal.hidden=false;$('trainingGoal').readOnly=true;}}catch(e){trainingFocusMessage(e.message,true);}};};
const originalPrivateReset=resetPrivateState;resetPrivateState=function(){trainingRevisionPending=null;sessionIndex.clear();sessionIndexOwner=null;for(const id of ['sessionHistoryContent','sessionConfigHistory','setupGuide','entryFinalSummary'])$(id)?.replaceChildren();bookRows=[];bookOwner=null;journalScope='current';originalPrivateReset();};

let entryStage=1;
function showEntryStage(n){entryStage=Math.max(1,Math.min(3,n));document.querySelectorAll('[data-entry-stage]').forEach(x=>x.hidden=Number(x.dataset.entryStage)!==entryStage);$('entryStageBack').hidden=entryStage===1;$('entryStageNext').hidden=entryStage===3||$('ideaOnly')?.checked;$('recordEntry').hidden=entryStage!==3||$('ideaOnly')?.checked;$('entryStageTitle').textContent=['1 / 3 · Setup & Idee vor dem Trade','2 / 3 · Konto & Risiko prüfen','3 / 3 · Verfassung & Entry'][entryStage-1];$('entryStageNext').textContent=entryStage===1?'Weiter · Konto & Risiko →':'Weiter · Verfassung →';$('entryForm').scrollIntoView({block:'start',behavior:'instant'});if(entryStage===3){const checks=[...$('allocationList').querySelectorAll('.acct-check:checked')];const parts=checks.map(c=>{const card=c.closest('.account');return card.querySelector('.acct-qty').value+' '+card.querySelector('.acct-instrument').value+' · '+card.querySelector('.acct-sl-ticks').value+' SL-Ticks';});const total=checks.reduce((n,c)=>{const card=c.closest('.account');return n+Number(card.querySelector('.acct-qty').value)*Number(card.querySelector('.acct-sl-ticks').value)*tickValues[card.querySelector('.acct-instrument').value];},0);$('entryFinalSummary').textContent=$('setup').value+' · '+$('direction').value.toUpperCase()+' · '+parts.join(' / ')+' · Gesamtrisiko '+usd(total)+' USD';}}
function initEntryStages(){const root=$('entryForm');const title=document.createElement('div');title.id='entryStageTitle';title.className='flow-step';const groups=[1,2,3].map(n=>{const g=document.createElement('div');g.dataset.entryStage=n;return g;});const first=$('setupCards');const start=root.querySelector('.setup-select-head');let node=start;const idea=$('ttIdeaPanel');while(node){const next=node.nextElementSibling;groups[0].append(node);if(node===idea)break;node=next;}groups[1].append($('entryAccounts'));groups[2].append($('entryEmotionOptions').closest('.emotion-section'),$('entryLimitField'));const intro=root.querySelector('.page-intro');const anchors=root.querySelector('.entry-steps');if(anchors)anchors.remove();root.querySelector('.flow-step')?.remove();intro?.after(title);title.after(...groups);const actions=document.createElement('div');actions.className='flow-actions';const back=document.createElement('button');back.id='entryStageBack';back.type='button';back.className='ghost';back.textContent='← Zurück';back.onclick=()=>showEntryStage(entryStage-1);const next=document.createElement('button');next.id='entryStageNext';next.type='button';next.onclick=()=>{if(entryStage===1){if(!$('setup').value){entryFeedback('Setup auswählen.',$('setupCards'));return;}if($('ttIdeaMode').value==='existing'&&!$('ttIdeaSelect').value){entryFeedback('Gespeicherte Idee wählen oder „Neue Idee“ auswählen.',$('ttIdeaSelect'));return;}if($('ttIdeaMode').value==='planned'){for(const id of ['ttIdeaThesis','ttIdeaTrigger','ttIdeaTarget','ttIdeaInvalidation'])if(!$(id).value.trim()){entryFeedback('Idee vervollständigen: These, Trigger, Ziel und Invalidation.',$(id));return;}}}if(entryStage===2){const selected=[...$('allocationList').querySelectorAll('.acct-check:checked')];if(!selected.length){entryFeedback('Konto auswählen.',$('allocationList'));return;}for(const c of selected){const card=c.closest('.account'),qty=Number(card.querySelector('.acct-qty').value),sl=Number(card.querySelector('.acct-sl-ticks').value);if(!Number.isSafeInteger(qty)||qty<1||!Number.isSafeInteger(sl)||sl<1||sl>100000){entryFeedback('Ganze Kontrakte und gültigen Standard-SL angeben.',card);return;}}}showEntryStage(entryStage+1);};actions.append(back,next);$('entryFeedback').before(actions);const sum=document.createElement('div');sum.id='entryFinalSummary';sum.className='flow-step';groups[2].prepend(sum);const only=$('ideaOnly');only.addEventListener('change',()=>{next.hidden=only.checked;$('recordEntry').hidden=only.checked||entryStage!==3;});showEntryStage(1);}
initEntryStages();

let ltfSaveChain=Promise.resolve();const originalLtfFlush=flushLtfAutosave;flushLtfAutosave=function(){const work=ltfSaveChain.catch(()=>{}).then(()=>originalLtfFlush());ltfSaveChain=work;return work;};
async function savePendingReviewImages(form){const zone=form?.querySelector('.trade-images .image-dropzone'),files=zone?chosenImages(zone):[];if(!files.length)return true;if(busy)return false;const owner=currentUser?.id,tradeId=form.dataset.tradeId,feedback=form.querySelector('.review-feedback'),btn=form.querySelector('.review-save');busy=true;btn.disabled=true;try{for(const file of files){const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';await uploadChart(file,chartPath('trade',tradeId,crypto.randomUUID()+'.'+ext));if(owner!==currentUser?.id)return false;const remaining=chosenImages(zone).filter(x=>x!==file);pendingImages.set(zone,remaining);}zone.querySelector('input[type=file]').value='';pendingImages.delete(zone);zone.querySelector('.image-pick-status').textContent='Bilder gespeichert';await renderTradeImages(tradeId);return true;}catch(e){feedback.textContent='Bilder nicht vollständig gespeichert: '+e.message+' · Review-Entwurf bleibt erhalten.';return false;}finally{busy=false;btn.disabled=false;}}
function renderConfigurationHistory(){const el=$('sessionAccountsSummary');if(!el)return;let history=$('sessionConfigHistory');if(!history){history=document.createElement('details');history.id='sessionConfigHistory';el.after(history);}history.replaceChildren();const rows=currentSession?.htf_context?.account_configuration_history||[];history.hidden=!rows.length;const label=document.createElement('summary');label.textContent='Vorgaben-Verlauf · '+rows.length+' Stände';history.append(label);for(const r of rows){const p=document.createElement('p');p.className='compact-help';p.textContent=berlinTime(r.changed_at)+' · '+(r.next||[]).map(a=>(allAccounts.find(x=>x.id===a.account_id)?.account_name||'Konto')+' '+(a.instrument||'')+' × '+(a.planned_quantity||'?')+' · SL '+(a.initial_sl_ticks||'?')).join(' / ');history.append(p);}el.closest('details.card').hidden=!currentSession;}
const sessionRender741=renderSession;renderSession=function(){sessionRender741();renderConfigurationHistory();};
